// Validate the human-approved payload and block replays by event_id.
// Seen event ids live in workflow static data, which n8n persists for production (active) executions.
const body = $input.first().json.body ?? {};
const errors = [];
if (body.schema_version !== 'agencyflow.v1') errors.push('unsupported schema_version');
if (typeof body.event_id !== 'string' || !/^af-\d+-[0-9a-f]{12}$/.test(body.event_id)) errors.push('missing or malformed event_id');
if (!body.reviewed_at) errors.push('plan was not human-approved (reviewed_at missing)');
const tasks = body.plan?.tasks;
if (!Array.isArray(tasks) || tasks.length === 0) errors.push('plan has no tasks');
if (errors.length) {
  return [{ json: { outcome: 'rejected', http: 422, response: { status: 'rejected', error: errors.join('; ') } } }];
}

// Cheap content fingerprint (djb2) so a reused event_id with different content is caught.
const text = JSON.stringify(body.plan);
let h = 5381;
for (let i = 0; i < text.length; i++) h = ((h << 5) + h + text.charCodeAt(i)) >>> 0;
const fingerprint = h.toString(16);

const store = $getWorkflowStaticData('global');
store.seen = store.seen ?? {};
const prev = store.seen[body.event_id];
if (prev && prev.fingerprint === fingerprint) {
  return [{ json: { outcome: 'duplicate', http: 200, response: { status: 'duplicate_ignored', duplicate: true, event_id: body.event_id, first_received_at: prev.at, external_actions: 'none' } } }];
}
if (prev) {
  return [{ json: { outcome: 'conflict', http: 409, response: { status: 'conflict', error: 'event_id already used for a different plan', event_id: body.event_id } } }];
}
store.seen[body.event_id] = { fingerprint, at: new Date().toISOString(), tasks: tasks.length };
const ids = Object.keys(store.seen);
if (ids.length > 500) for (const id of ids.slice(0, ids.length - 500)) delete store.seen[id];

return [{ json: { outcome: 'accepted', http: 200, event: body } }];

// Map the approved plan into generic tracker cards. Dry run: nothing leaves n8n.
const e = $input.first().json.event;
const cards = e.plan.tasks.map((t, i) => ({
  external_ref: `${e.event_id}#${i + 1}`,
  title: t.title,
  assignee_role: t.role,
  priority: t.priority,
  due_date: t.due_date ?? null,
  description: t.detail,
}));
return [{ json: { event_id: e.event_id, campaign: e.plan.campaign_name, deadline: e.plan.deadline ?? null, open_questions: e.plan.missing_inputs ?? [], cards } }];
